// Release manifests and preflight (src/helpers/updates/, docs/contract/UPDATES.md sections 3 and 4), against the public
// update vectors (test/fixtures/updates_public_v1.json, generated by tools/mecon_update_vectors.py).
#include <gtest/gtest.h>
#include <string.h>
#include <string>
#include "helpers/deployment/DepAuthority.h"
#include "helpers/deployment/DepHmac.h"
#include "helpers/iface/Jobs.h"
#include "helpers/updates/UpdB64.h"
#include "helpers/updates/UpdPreflight.h"
#include "vectors.h"

using namespace Upd;

namespace {

// The device the vectors are made for.
Device testDevice() {
  Device d = {};
  d.line = "public";
  d.hardware = "Test Board";
  d.hardware_rev = "1";
  d.role = "companion";
  d.variant = "test_variant";
  d.layout = 1;
  d.kinds = 1u << KIND_APP;
  d.security_floor = 1;
  d.running_known = parseVersion("v1.18.0-mecon.0.2.0", &d.running);
  d.slot_size = 0x640000;
  d.free_heap = 100000;
  d.heap_needed = 48 * 1024;
  return d;
}

// The staging checks in their order (parse, key, signature, target): the error, or nullptr when all pass.
const char* stage(const UpdVector& v, const Device& d, Manifest* m) {
  if (!parseManifest(v.manifest, strlen(v.manifest), m)) return "bad-manifest";
  const Anchor* a = nullptr;
  Verdict r = checkKey(*m, nullptr, 0, &a);
  if (!r.ok) return r.error;
  uint8_t sig[SIG_LEN];
  if (!Dep::base64ToSig(v.sig, strlen(v.sig), sig)) return "bad-args";
  if (!verifyManifest(v.manifest, strlen(v.manifest), sig, a->key)) return "bad-release-signature";
  r = checkTarget(*m, d);
  return r.ok ? nullptr : r.error;
}

Manifest valid() {
  Manifest m;
  EXPECT_TRUE(parseManifest(UPD_VALID.manifest, strlen(UPD_VALID.manifest), &m));
  return m;
}

}  // namespace

TEST(UpdVectors, TheValidManifestStages) {
  Manifest m;
  EXPECT_EQ(nullptr, stage(UPD_VALID, testDevice(), &m));
  EXPECT_STREQ("v1.18.0-mecon.0.3.0", m.version);
  EXPECT_EQ(KIND_APP, m.kind);
  EXPECT_EQ(1234u, m.image_size);
  EXPECT_FALSE(m.has_bootloader_min);
}

TEST(UpdVectors, TheLongestManifestParsesAndVerifies) {
  Manifest m;
  ASSERT_LE(strlen(UPD_LONGEST.manifest), MANIFEST_MAX);
  ASSERT_TRUE(parseManifest(UPD_LONGEST.manifest, strlen(UPD_LONGEST.manifest), &m));
  const Anchor* a = findAnchor(m.key_id);
  ASSERT_NE(nullptr, a);
  uint8_t sig[SIG_LEN];
  ASSERT_TRUE(Dep::base64ToSig(UPD_LONGEST.sig, strlen(UPD_LONGEST.sig), sig));
  EXPECT_TRUE(verifyManifest(UPD_LONGEST.manifest, strlen(UPD_LONGEST.manifest), sig, a->key));
  EXPECT_TRUE(m.has_bootloader_min);
  EXPECT_EQ(KIND_BOOTLOADER_DFU, m.kind);
}

TEST(UpdVectors, EachRefusedVectorGetsItsCode) {
  for (const UpdVector& v : UPD_REFUSED) {
    Manifest m;
    const char* e = stage(v, testDevice(), &m);
    ASSERT_NE(nullptr, e) << v.name;
    EXPECT_STREQ(v.error, e) << v.name;
  }
}

TEST(UpdVectors, OneChangedByteBreaksTheSignature) {
  std::string t = UPD_VALID.manifest;
  t[t.find("0.3.0")] = '1';   // still a well-formed manifest
  UpdVector v = {"tampered", t.c_str(), UPD_VALID.sig, nullptr};
  Manifest m;
  EXPECT_STREQ("bad-release-signature", stage(v, testDevice(), &m));
}

TEST(UpdManifest, StrictParsing) {
  std::string t = UPD_VALID.manifest;
  Manifest m;
  auto refused = [&](std::string s) { return !parseManifest(s.c_str(), s.size(), &m); };
  std::string bumped = t;
  bumped.replace(bumped.find("\"v\":1"), 5, "\"v\":2");
  EXPECT_TRUE(refused(bumped)) << "version 2 is not this parser's";
  std::string img = t;
  img.replace(img.find("\"size\":1234"), 11, "\"size\":1234,\"x\":1");
  EXPECT_TRUE(refused(img)) << "an unknown key inside image";
  std::string upper = t;
  size_t k = upper.find("\"key_id\":\"") + 10;
  while (!(upper[k] >= 'a' && upper[k] <= 'f')) k++;   // the first hex letter of the key id
  upper[k] = (char)(upper[k] - 'a' + 'A');
  EXPECT_TRUE(refused(upper)) << "hex is lowercase";
  std::string kind = t;
  kind.replace(kind.find("\"kind\":\"app\""), 12, "\"kind\":\"apk\"");
  EXPECT_TRUE(refused(kind));
  std::string big(MANIFEST_MAX + 1, ' ');
  EXPECT_TRUE(refused(big));
  std::string norevs = t;
  norevs.replace(norevs.find("\"hardware_rev\":[\"1\"]"), 20, "\"hardware_rev\":[]");
  EXPECT_TRUE(refused(norevs)) << "an image supports at least one board revision";
}

TEST(UpdVersion, OrderAndDevelopmentBuilds) {
  Version a, b;
  ASSERT_TRUE(parseVersion("v1.18.0-mecon.0.1.2", &a));
  ASSERT_TRUE(parseVersion("v1.18.0-mecon.0.1.2+5.gabc1234.dirty", &b));
  EXPECT_EQ(0, compareVersion(a, b)) << "a build after a tag compares as the tag";
  ASSERT_TRUE(parseVersion("v1.18.0-mecon.0.2.0-rc.1", &b));
  EXPECT_LT(compareVersion(a, b), 0);
  Version r;
  ASSERT_TRUE(parseVersion("v1.18.0-mecon.0.2.0", &r));
  EXPECT_GT(compareVersion(r, b), 0) << "a release above its pre-release";
  ASSERT_TRUE(parseVersion("v1.18.0-mecon.0.10.0", &b));
  EXPECT_GT(compareVersion(b, r), 0) << "numeric, not text";
  EXPECT_FALSE(parseVersion("v1.18.0-mecon.unknown", &b));
  EXPECT_FALSE(parseVersion("v1.18.0-mecon.0.1", &b));
}

TEST(UpdTarget, EveryMismatchIsWrongTarget) {
  const Manifest m = valid();
  const Device base = testDevice();
  EXPECT_TRUE(checkTarget(m, base).ok);
  Device d = base; d.hardware = "Other";        EXPECT_STREQ("wrong-target", checkTarget(m, d).error);
  d = base; d.hardware_rev = "2";               EXPECT_STREQ("wrong-target", checkTarget(m, d).error);
  d = base; d.role = "repeater";                EXPECT_STREQ("wrong-target", checkTarget(m, d).error);
  d = base; d.variant = "other_variant";        EXPECT_STREQ("wrong-target", checkTarget(m, d).error);
  d = base; d.layout = 2;                       EXPECT_STREQ("wrong-target", checkTarget(m, d).error);
  d = base; d.line = "private";                 EXPECT_STREQ("wrong-target", checkTarget(m, d).error);
  d = base; d.kinds = 1u << KIND_BOOTLOADER_DFU; EXPECT_STREQ("wrong-target", checkTarget(m, d).error);
  Manifest bm = m;
  bm.has_bootloader_min = true; bm.bootloader_min = 5;
  d = base; d.has_bootloader = true; d.bootloader = 4;
  EXPECT_STREQ("wrong-target", checkTarget(bm, d).error);
  d.bootloader = 5;
  EXPECT_TRUE(checkTarget(bm, d).ok);
}

TEST(UpdPreflight, TheInstallChecksInOrder) {
  const Manifest m = valid();   // 0.3.0, security 1, min_from 0.1.0, 1234 bytes
  const Device base = testDevice();   // runs 0.2.0, floor 1
  EXPECT_TRUE(checkInstall(m, base, false).ok);

  Device d = base; d.security_floor = 2;
  EXPECT_STREQ("below-security-floor", checkInstall(m, d, true).error) << "the floor holds even for a signed offer";
  d = base; d.running_known = parseVersion("v1.18.0-mecon.0.0.9", &d.running);
  EXPECT_STREQ("below-min-from", checkInstall(m, d, false).error);
  d = base; d.running_known = false;
  EXPECT_STREQ("below-min-from", checkInstall(m, d, false).error) << "an unknown running version is never at least min_from";

  Manifest old = m;
  strcpy(old.version, "v1.18.0-mecon.0.1.5");
  EXPECT_STREQ("downgrade-refused", checkInstall(old, base, true).error) << "the manifest must allow it";
  old.downgrade = true;
  EXPECT_STREQ("downgrade-refused", checkInstall(old, base, false).error) << "and a Deployment member must sign the offer";
  EXPECT_TRUE(checkInstall(old, base, true).ok);

  d = base; d.slot_size = 1000;
  EXPECT_STREQ("too-large", checkInstall(m, d, false).error);
  d = base; d.free_heap = 1000;
  const Verdict v = checkInstall(m, d, false);
  EXPECT_STREQ("busy", v.status);
  EXPECT_STREQ("low-memory", v.error);
}

